DROP TABLE IF EXISTS `flow_leave`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `flow_leave` (
  `leave_id` bigint NOT NULL AUTO_INCREMENT COMMENT '请假单ID',
  `title` varchar(100) COLLATE utf8mb4_general_ci NOT NULL COMMENT '请假标题',
  `leave_type` char(1) COLLATE utf8mb4_general_ci DEFAULT '1' COMMENT '请假类型（1事假 2病假 3年假 4调休）',
  `start_date` date DEFAULT NULL COMMENT '开始日期',
  `end_date` date DEFAULT NULL COMMENT '结束日期',
  `days` decimal(5,1) DEFAULT '0.0' COMMENT '请假天数',
  `reason` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '请假事由',
  `status` char(1) COLLATE utf8mb4_general_ci DEFAULT '0' COMMENT '状态（0草稿 1审批中 2已通过 3已驳回 4已撤销）',
  `instance_id` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '流程实例ID',
  `start_user_id` bigint DEFAULT NULL COMMENT '申请人ID',
  `start_user_name` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '申请人姓名',
  `audit_opinion` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '最终审批意见',
  `del_flag` char(1) COLLATE utf8mb4_general_ci DEFAULT '0' COMMENT '删除标志（0存在 2删除）',
  `create_by` varchar(64) COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`leave_id`),
  KEY `idx_start_user` (`start_user_id`),
  KEY `idx_instance` (`instance_id`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='请假单（工作流示例业务表）';
/*!40101 SET character_set_client = @saved_cs_client */;

